// Research only. In-memory fixtures; no Relay API, storage, or provider calls.
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Checkout error rate above 12%','Payments latency above SLO','Inventory refresh delayed','Search timeout rate elevated','Authentication errors rising'];
const services=['Checkout API','Payments API','Inventory','Search','Identity'];
const state={alerts:[],selected:1,checked:new Set(),page:0,filter:'all',query:'',incident:null,view:'inbox',publicDraft:null};
let noticeTimer,returnFocus;
function say(message){$('#notice').textContent=message;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').textContent='',6000)}
function seed(n){state.alerts=Array.from({length:n},(_,i)=>({id:i+1,title:names[i%5],service:services[i%5],severity:i%5===0?'SEV2':'SEV3',status:'Needs response',owner:'Unassigned',failed:i%11===0,group:null}));state.selected=1;state.checked.clear();state.page=0;state.incident=null;state.publicDraft=null;state.view='inbox';render()}
const current=()=>state.alerts.find(a=>a.id===state.selected);
const visible=()=>state.alerts.filter(a=>(state.filter==='all'||state.filter==='needs'&&a.status==='Needs response'||state.filter==='failed'&&a.failed||state.filter==='mine'&&a.owner==='Ada')&&`${a.title} ${a.service} ALT-${a.id}`.toLowerCase().includes(state.query.toLowerCase()));
function nav(){for(const [id,view] of [['inbox-nav','inbox'],['incident-nav','incident']]){const b=$('#'+id);if(state.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}$('#incident-nav').disabled=!state.incident}
function render(){nav();if(state.view==='inbox')renderInbox();else renderIncident()}
function renderInbox(){
 const list=visible(),pageCount=Math.max(1,Math.ceil(list.length/25));state.page=Math.min(state.page,pageCount-1);
 const pageRows=list.slice(state.page*25,(state.page+1)*25);if(pageRows.length&&!pageRows.some(a=>a.id===state.selected))state.selected=pageRows[0].id;
 $('#main').innerHTML=`<div class="heading"><div><h1>Alert inbox</h1><span class="muted">Triage the signal. Keep ownership and paging outcomes visible.</span></div><span class="pill">${state.alerts.length} alerts · fixture snapshot</span></div>
 <div class="facts"><div><small>Needs response</small><strong>${state.alerts.filter(a=>a.status==='Needs response').length}</strong></div><div><small>Delivery failures</small><strong>${state.alerts.filter(a=>a.failed).length} need attention</strong></div><div><small>Checkout pages now</small><strong>Ada · Primary rotation</strong></div><div><small>Next handoff</small><strong>16:00 UTC → Ben</strong></div></div>
 <div class="toolbar"><label for="search">Search</label><input type="search" id="search" placeholder="Title, service or ALT-ID" value="${esc(state.query)}"><label for="filter">Show</label><select id="filter"><option value="all">All alerts</option><option value="needs">Needs response</option><option value="failed">Delivery failed</option><option value="mine">Assigned to me</option></select><span class="kbd">/ search · j / k move focused row</span></div>
 <div class="toolbar"><strong id="selection-count">${state.checked.size} selected</strong><button id="bulk-ack" ${state.checked.size?'':'disabled'}>Acknowledge selected</button><button id="group" ${state.checked.size>1?'':'disabled'}>Group selected…</button><small>Selection applies to this page only.</small></div>
 <div class="inbox"><section class="queue" aria-label="Alert queue"><div class="queue-head"><label><input id="select-page" type="checkbox" aria-label="Select current page"></label><span>Signal / service</span><span>State</span><span>Owner</span></div>
 ${list.slice(state.page*25,(state.page+1)*25).map(a=>`<div class="alert-row ${a.id===state.selected?'selected':''}"><input type="checkbox" data-check="${a.id}" aria-label="Select ALT-${a.id}" ${state.checked.has(a.id)?'checked':''}><button class="alert-open" data-open="${a.id}" aria-pressed="${a.id===state.selected}"><strong>${esc(a.title)}</strong><small>ALT-${a.id} · ${esc(a.service)} · ${a.severity}${a.group?' · Group '+esc(a.group):''}${a.failed?' · Delivery failed':''}</small></button><span class="pill ${a.status==='Needs response'?'warn':a.status==='Acknowledged'?'good':''}">${esc(a.status)}</span><small>${esc(a.owner)}</small></div>`).join('')||'<div class="empty">No matching alerts. Change the search or filter; the workspace is not necessarily quiet.</div>'}
 <div class="pagination"><span>${list.length?state.page*25+1:0}–${Math.min((state.page+1)*25,list.length)} of ${list.length}</span><button id="previous" ${state.page?'':'disabled'}>Previous</button><button id="next" ${state.page<pageCount-1?'':'disabled'}>Next 25</button></div></section><aside class="detail" aria-label="Selected alert">${pageRows.length?alertDetail(current()):'<p>No matching alert selected.</p>'}</aside></div>`;
 $('#filter').value=state.filter;
 $('#search').oninput=e=>{const pos=e.target.selectionStart;state.query=e.target.value;state.page=0;state.checked.clear();renderInbox();$('#search').focus();$('#search').setSelectionRange(pos,pos)};
 $('#filter').onchange=e=>{state.filter=e.target.value;state.page=0;state.checked.clear();renderInbox();$('#filter').focus()};
 document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{state.selected=Number(b.dataset.open);renderInbox();$(`[data-open="${state.selected}"]`).focus();if(innerWidth<701){$('.detail').scrollIntoView();$('#ack')?.focus()}});
 document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{const id=Number(b.dataset.check);b.checked?state.checked.add(id):state.checked.delete(id);renderInbox();$(`[data-check="${id}"]`).focus()});
 $('#select-page').onchange=e=>{state.checked=e.target.checked?new Set(list.slice(state.page*25,(state.page+1)*25).map(a=>a.id)):new Set();renderInbox();$('#select-page').focus()};
 for(const [id,delta]of [['previous',-1],['next',1]])$('#'+id).onclick=()=>{state.page+=delta;state.checked.clear();renderInbox();$('.alert-open')?.focus()};
 $('#bulk-ack').onclick=()=>confirmBulk();$('#group').onclick=()=>group();
 $('#ack')?.addEventListener('click',()=>{ack(current());renderInbox();$('#create')?.focus();say('Acknowledged by Ada. Unsent pages cancelled in this simulation; prior failures remain visible.')});
 $('#create')?.addEventListener('click',()=>createIncident());$('#assign')?.addEventListener('click',()=>assign());$('#suppress')?.addEventListener('click',()=>suppress());$('#resume')?.addEventListener('click',()=>{current().status='Needs response';renderInbox();say('Suppression ended. Signal needs response again.')});$('#open-existing')?.addEventListener('click',()=>{state.view='incident';render()});$('#page-backup')?.addEventListener('click',()=>pageBackup());
}
function alertDetail(a){return `<p class="muted">ALT-${a.id} · Source: synthetic monitor · first seen 14:02 UTC</p><h2>${esc(a.title)}</h2><p><span class="pill ${a.status==='Needs response'?'warn':a.status==='Acknowledged'?'good':''}">${esc(a.status)}</span> <span class="pill">${a.severity}</span></p><dl><dt>Current owner</dt><dd>${esc(a.owner)}</dd><dt>Page target</dt><dd>Ada · resolved at 14:02 UTC</dd><dt>Delivery</dt><dd>${a.failed?'<span class="danger">Failed · webhook unavailable</span>':'Accepted by provider · receipt unconfirmed'}</dd><dt>Backup</dt><dd>${a.status==='Acknowledged'?'Cancelled by acknowledgement':'Ben · after 5 minutes'}</dd><dt>Public status</dt><dd>${state.incident?.alertId===a.id?(state.incident.public?esc(state.incident.public.status)+' · public update exists':'Incident exists · not published'):'No public incident linked to this alert'}</dd></dl><div class="toolbar"><button id="ack" class="primary" ${a.status==='Acknowledged'?'disabled':''}>${a.status==='Acknowledged'?'Acknowledged':'Acknowledge'}</button><button id="assign">Assign…</button></div><div class="toolbar">${state.incident?.alertId===a.id?'<button id="open-existing">Open INC-42</button>':'<button id="create">Create incident…</button>'}<button id="page-backup">Page backup…</button></div><section><h3>Signal context</h3><p>Failures increased after the 13:58 deployment. Request impact is unconfirmed.</p><p><strong>Next action:</strong> confirm impact before changing public status.</p><details><summary>Routing and source evidence</summary><p>Checkout criticals → Primary rotation → Ada. This is the decision recorded when the page was created.</p><pre>source: synthetic-monitor\nregion: eu-west\ninternal host: checkout-db.internal\nmetadata: INTERNAL_FIXTURE_ONLY</pre></details><div class="toolbar">${a.status==='Suppressed'?'<button id="resume">End suppression</button>':'<button id="suppress">Suppress for 15 min…</button>'}</div></section>`}
function ack(a){a.status='Acknowledged';a.owner='Ada'}
function modal(title,body,onSubmit){returnFocus=document.activeElement;const d=$('#dialog');d.innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;d.showModal();d.querySelector('[data-cancel]')?.addEventListener('click',()=>d.close());d.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();onSubmit(new FormData(e.target))});d.querySelector('input,textarea,select,button')?.focus()}
$('#dialog').addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus();else if(state.view==='incident')$('#main').focus();else $('.alert-open')?.focus()});
$('#dialog').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=[...e.currentTarget.querySelectorAll('button,input,select,textarea')].filter(x=>!x.disabled),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
for(const event of ['input','change'])$('#dialog').addEventListener(event,()=>{if($('#dialog-title')?.textContent==='Draft customer update')state.publicDraft=Object.fromEntries(new FormData($('#dialog form')))});
const actions=(label)=>`<div class="dialog-actions"><button type="button" data-cancel>Cancel</button><button class="primary" type="submit">${label}</button></div>`;
function confirmBulk(){const ids=[...state.checked];modal('Acknowledge selected alerts',`<form><p>Take ownership as Ada and stop unsent pages for exactly ${ids.length} selected alerts on this page.</p><p>${ids.map(id=>'ALT-'+id).join(', ')}</p>${actions('Acknowledge '+ids.length+' alerts')}</form>`,()=>{ids.forEach(id=>ack(state.alerts.find(a=>a.id===id)));state.checked.clear();$('#dialog').close();renderInbox();say(`${ids.length} alerts acknowledged. No hidden rows were changed.`)})}
function group(){const ids=[...state.checked];modal('Group related signals',`<form><p>Group ${ids.length} selected alerts for inspection. No acknowledgement, paging cancellation or incident creation is implied.</p><label>Reason<input name="reason" required placeholder="Same deployment and service dependency"></label>${actions('Group '+ids.length+' alerts')}</form>`,()=>{ids.forEach(id=>state.alerts.find(a=>a.id===id).group='G1');state.checked.clear();$('#dialog').close();renderInbox();say('Explicit grouping recorded for selected fixtures. Source alerts remain separate.')})}
function assign(){modal('Assign current alert',`<form><label>Owner<select name="owner"><option>Ada</option><option>Ben</option><option>Chen</option></select></label><p>Assignment records responsibility. It does not prove acknowledgement or notify a provider in this prototype.</p>${actions('Assign alert')}</form>`,f=>{current().owner=f.get('owner');$('#dialog').close();renderInbox();say('Owner updated.')})}
function suppress(){modal('Suppress ALT-'+current().id,`<form><p>Hide notifications for this signal for 15 minutes. Keep the record and owner. This prototype requires “End suppression” to simulate expiry.</p><label>Reason<input name="reason" required></label>${actions('Suppress 15 minutes')}</form>`,()=>{current().status='Suppressed';$('#dialog').close();renderInbox();say('Suppression active for this fixture. Use End suppression to resume.')})}
function pageBackup(){modal('Page backup responder',`<form><p><strong>Ben · Checkout backup</strong></p><p>One email page would be queued now. No public change. Recipient is rechecked at submission in a production design.</p>${actions('Simulate page to Ben')}</form>`,()=>{$('#dialog').close();say('Simulation: page to Ben accepted by provider. Human acknowledgement unknown.')})}
function createIncident(){const a=current();modal('Create incident from ALT-'+a.id,`<form><label>Incident title<input name="title" value="${esc(a.title)}" required minlength="3"></label><label>Severity<select name="severity"><option ${a.severity==='SEV2'?'selected':''}>SEV2</option><option ${a.severity==='SEV3'?'selected':''}>SEV3</option><option>SEV1</option><option>SEV4</option></select></label><label>Incident commander<select name="owner"><option>Ada</option><option>Ben</option><option>Chen</option></select></label><p><strong>Affected service:</strong> ${esc(a.service)}</p><p><strong>Responders:</strong> Ada + Ben. Simulation will record a channel delivery receipt; joining remains unconfirmed.</p><p><strong>Public status:</strong> no components selected; no publication. Public drafts start separately.</p>${actions('Create internal incident')}</form>`,f=>{state.incident={alertId:a.id,title:f.get('title'),severity:f.get('severity'),owner:f.get('owner'),service:a.service,status:'Investigating',next:'14:30 UTC',notes:[],events:['Incident declared by Ada. Responders Ada and Ben invited (simulated).'],public:null,tasks:[false,false],retro:''};$('#dialog').close();state.view='incident';render();$('#main').focus();say('INC-42 created. Commander assigned; simulated delivery accepted. Responders have not confirmed joining.')})}
function renderIncident(){const i=state.incident;
 $('#main').innerHTML=`<div class="command-head"><div class="heading"><div><p class="muted">INC-42 · ${esc(i.service)} · started 14:05 UTC</p><h1>${esc(i.title)}</h1><span class="pill warn">${i.severity}</span> <span class="pill ${i.status==='Resolved'?'good':''}">${i.status}</span></div><div class="toolbar"><button id="change-owner">Change commander</button>${i.status==='Resolved'?'<button id="post-incident" class="primary">Post-incident review</button>':'<button id="resolve">Resolve incident…</button>'}</div></div><div class="facts"><div><small>Incident commander</small><strong>${esc(i.owner)}</strong></div><div><small>Technical owner</small><strong>Ada · ${i.status==='Resolved'?'response ended':'investigating'}</strong></div><div><small>Responder receipt</small><strong>Provider accepted · join unconfirmed</strong></div><div><small>Next internal update</small><strong>${i.status==='Resolved'?'Response ended':esc(i.next)}</strong></div><div><small>Public status</small><strong>${i.public?esc(i.public.status)+' · published locally':'Not published'}</strong></div></div></div>
 <div class="command"><div><section class="panel"><h2>Current response</h2><p>Confirm customer impact and validate the rollback. Keep the handoff brief.</p><div class="task"><label><input type="checkbox" data-task="0" ${i.tasks[0]?'checked':''}><span>Validate rollback on Checkout<small>Ada · due 14:20 UTC</small></span></label><span class="pill">${i.tasks[0]?'Done':'In progress'}</span></div><div class="task"><label><input type="checkbox" data-task="1" ${i.tasks[1]?'checked':''}><span>Check payment success rate<small>Ben · due 14:25 UTC</small></span></label><span class="pill">${i.tasks[1]?'Done':'Waiting'}</span></div><details><summary>Runbook · Checkout recovery</summary><ol><li>Confirm scope using service metrics.</li><li>Ask the deployment owner to assess rollback safety.</li><li>Record the decision and verify recovery.</li></ol><p>This fixture runs no commands.</p></details></section>
 <section class="panel"><h2>Internal update</h2><form id="note-form"><label for="note">Operational notes · visible only to responders</label><textarea id="note" name="note" required placeholder="What changed, who is doing what, and when will we update?"></textarea><div class="toolbar"><label>Next update<select name="next"><option>14:30 UTC</option><option>14:45 UTC</option><option>15:00 UTC</option></select></label><button class="primary">Add internal update</button></div></form>${i.notes.map(n=>`<div class="note"><small>Internal · Ada · fixture clock 14:10 UTC</small>${esc(n)}</div>`).join('')}</section>
 <section class="panel"><h2>Timeline</h2><ol class="timeline">${i.events.map(e=>`<li><time>14:${String(5+i.events.indexOf(e)).padStart(2,'0')} UTC</time>${esc(e)}</li>`).join('')}</ol><small>Fixed fixture clock; event times illustrate order, not elapsed response time.</small></section></div>
 <aside><section class="panel public"><h2>Public communication</h2><p><strong>${i.public?'Last published update':'No public update published'}</strong></p>${i.public?`<p>${esc(i.public.title)}</p><p class="note">${esc(i.public.message)}</p><p>${esc(i.public.page)} · ${esc(i.public.component)} · ${esc(i.public.status)}</p>`:'<p>Customers cannot see the internal notes, source alerts, or responder identities.</p>'}<p><strong>Next customer update:</strong> ${i.public?esc(i.public.next):'Not promised'}</p><button id="compose-public">Draft public update…</button><details><summary>Inspect customer-visible projection</summary><div class="public-preview">${i.public?`<h3>${esc(i.public.title)}</h3><p>${esc(i.public.status)}</p><p>${esc(i.public.message)}</p><p>Next update ${esc(i.public.next)}</p>`:'Nothing published.'}</div></details></section><section class="panel"><h2>Linked alert</h2><button id="linked-alert">ALT-${i.alertId} · view signal & paging history</button><p class="muted">Alert acknowledgement and incident resolution are separate actions.</p></section><section class="panel"><h2>Responders</h2><p><strong>${esc(i.owner)}</strong> · commander</p><p><strong>Ben</strong> · invited, not confirmed</p><p>Channel delivery: accepted by provider (simulation).</p></section>${i.status==='Resolved'?'<section class="panel"><h2>Learning handoff</h2><p>Assign review ownership and one concrete follow-up. Unfinished response tasks remain recorded.</p><p id="retro-summary">'+esc(i.retro||'Review has not been saved.')+'</p></section>':''}</aside></div>`;
 $('#note-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);i.notes.push(f.get('note'));i.next=f.get('next');i.events.push('Internal update added; public text unchanged.');renderIncident();$('#note').focus();say('Internal update saved. No public change.')};
 document.querySelectorAll('[data-task]').forEach(c=>c.onchange=()=>{i.tasks[Number(c.dataset.task)]=c.checked;const id=c.dataset.task;renderIncident();$(`[data-task="${id}"]`).focus()});
 $('#compose-public').onclick=composePublic;$('#resolve')?.addEventListener('click',resolve);$('#post-incident')?.addEventListener('click',postIncident);
 $('#linked-alert').onclick=()=>{state.selected=i.alertId;state.view='inbox';render()};
 $('#change-owner').onclick=()=>modal('Change incident commander',`<form><label>Commander<select name="owner"><option>Ada</option><option>Ben</option><option>Chen</option></select></label><p>Record the handoff explicitly. Role assignment is not permission elevation.</p>${actions('Record handoff')}</form>`,f=>{i.owner=f.get('owner');i.events.push('Commander handed over to '+i.owner);$('#dialog').close();renderIncident()});
}
function composePublic(){const d=state.publicDraft??{title:'',message:'',status:state.incident.status==='Resolved'?'Resolved':'Investigating',next:'14:45 UTC'};modal('Draft customer update',`<form><p>Destination: <strong>Northstar public status</strong>. Audience: anyone on the internet. This draft starts independently from internal notes.</p><label>Public title<input name="title" required value="${esc(d.title)}" placeholder="Checkout availability"></label><label>Public message<textarea name="message" required placeholder="Describe customer impact and the next update.">${esc(d.message)}</textarea></label><label>Customer-visible state<select name="status">${['Investigating','Identified','Monitoring','Resolved'].map(s=>`<option ${s===d.status?'selected':''}>${s}</option>`).join('')}</select></label><label>Affected public component<select name="component"><option>${esc(state.incident.service.replace(' API',''))}</option></select></label><label>Next customer update<input name="next" required value="${esc(d.next)}"></label>${actions('Review public update')}</form>`,f=>{state.publicDraft=Object.fromEntries(f);$('#dialog').close();reviewPublic()})}
function reviewPublic(){const d={...state.publicDraft,page:'Northstar public status'};modal('Review exact public update',`<form><p><strong>Audience: public internet</strong> · Northstar public status</p><div class="review"><strong>${esc(d.title)}</strong><p>${esc(d.status)} · ${esc(d.component)}</p><p>${esc(d.message)}</p><p>Next update: ${esc(d.next)}</p></div><p>Only the displayed fields will enter this prototype’s public projection. Internal notes, alert payloads, roster and routing remain excluded.</p><p class="error" id="publish-error" role="alert"></p><div class="dialog-actions"><button type="button" id="edit-public">Back to draft</button><button type="button" data-cancel>Cancel</button><button class="primary" type="submit">Publish public update</button></div></form>`,()=>{if($('#failure').checked){$('#publish-error').textContent='Simulated delivery failure. Nothing published. Your draft is preserved; turn off the failure switch and retry.';return}state.incident.public=d;state.incident.events.push('Public update published to Northstar public status.');state.publicDraft=null;$('#dialog').close();renderIncident();say('Published locally to the fixture customer view. No external destination was contacted.')});$('#edit-public').onclick=()=>{$('#dialog').close();composePublic()}}
function resolve(){const i=state.incident;modal('Resolve internal response',`<form><p>${i.tasks.filter(x=>!x).length} response tasks remain open; carry them into review.</p><p><strong>Public state:</strong> ${i.public?esc(i.public.status):'Not published'}. This prototype models independent public publication: resolving here does not change that state. Relay 0.2 currently couples these states; A4 must decide the model.</p><label>Resolution evidence<textarea name="evidence" required placeholder="Recovery verified in metrics; remaining customer impact…"></textarea></label>${actions('Resolve internal incident')}</form>`,f=>{i.status='Resolved';i.events.push('Internal response resolved: '+f.get('evidence'));$('#dialog').close();renderIncident();say('Internal response resolved. Review the public status separately.')})}
function postIncident(){modal('Post-incident handoff',`<form><label>Review owner<select name="owner"><option>Ada</option><option>Ben</option></select></label><label>Review date<input type="date" name="date" required value="2026-09-30"></label><label>Learning and follow-up<textarea name="followup" required placeholder="Investigate the deployment guardrail; owner and evidence of success.">${esc(state.incident.retro)}</textarea></label><p>Timeline and unfinished tasks remain attached. No root cause is inferred.</p>${actions('Save review handoff')}</form>`,f=>{state.incident.retro=`${f.get('owner')} · ${f.get('date')} · ${f.get('followup')}`;state.incident.events.push('Post-incident review handoff recorded.');$('#dialog').close();renderIncident();say('Review handoff saved in this session.')})}
$('#volume').onchange=e=>seed(Number(e.target.value));$('#inbox-nav').onclick=()=>{state.view='inbox';render()};$('#incident-nav').onclick=()=>{state.view='incident';render()};
document.addEventListener('keydown',e=>{if($('#dialog').open||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='/'&&state.view==='inbox'){e.preventDefault();$('#search').focus()}if(['j','k'].includes(e.key)&&e.target.matches('[data-open]')){e.preventDefault();const rows=[...document.querySelectorAll('[data-open]')],index=rows.indexOf(e.target)+(e.key==='j'?1:-1);rows[Math.max(0,Math.min(rows.length-1,index))]?.focus()}});
seed(50);
